from codeop import compile_command, PyCF_DONT_IMPLY_DEDENT

def _t():
    assert compile_command('a = 1\n', 'abc').co_filename == compile('a = 1\n', 'abc', 'single').co_filename, ('assertEqual', compile_command('a = 1\n', 'abc').co_filename, compile('a = 1\n', 'abc', 'single').co_filename)
    assert compile_command('a = 1\n', 'abc').co_filename != compile('a = 1\n', 'def', 'single').co_filename, ('assertNotEqual', compile_command('a = 1\n', 'abc').co_filename, compile('a = 1\n', 'def', 'single').co_filename)
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

import warnings
from codeop import compile_command, PyCF_DONT_IMPLY_DEDENT

def assertIncomplete(str, symbol='single'):
    """succeed iff str is the start of a valid piece of code"""
    assert compile_command(str, symbol=symbol) == None, ('assertEqual', compile_command(str, symbol=symbol), None)

def _t():
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter('always')
        assertIncomplete("'\\e' + (")
    assert w == [], ('assertEqual', w, [])
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

import re as _re
from textwrap import dedent
from codeop import compile_command, PyCF_DONT_IMPLY_DEDENT

def assertSyntaxErrorMatches(code, message):
    try:
        compile_command(code, symbol='exec')
    except SyntaxError as _exc:
        assert _re.search(message, str(_exc)), 'assertRaisesRegex: message mismatch'
    else:
        raise AssertionError('assertRaises: did not raise')

def _t():
    assertSyntaxErrorMatches(dedent('                def foo(x,x):\n                   pass\n            '), "duplicate argument 'x' in function definition")
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')
